101	/* ============ tools hub: search + category filter over the real tool catalogue ============ */
102	(function toolsDir() {
103	  const q = $('#th-q'), seg = $('.th-seg'), none = $('#th-none'), groups = $$('.th-grp');
104	  if (!q || !groups.length) return;
105	  let cat = 'all';
106	  const norm = s => (s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]+/g, ' ');
107	  const apply = () => {
108	    const words = norm(q.value).split(' ').filter(Boolean);
109	    let shown = 0;
110	    groups.forEach(g => {
111	      const inCat = cat === 'all' || g.dataset.cat === cat;
112	      let n = 0;
113	      $$('.th-card', g).forEach(c => {
114	        const hay = norm(c.dataset.find);
115	        const ok = inCat && words.every(w => hay.includes(w));
116	        c.hidden = !ok; if (ok) n++;
117	      });
118	      g.hidden = n === 0; shown += n;
119	    });
120	    none.hidden = shown > 0;
121	  };
122	  q.addEventListener('input', apply);
123	  if (seg) seg.addEventListener('change', e => { cat = e.detail || 'all'; apply(); });
124	  // deep link: /tools?q=dns
125	  const pre = new URLSearchParams(location.search).get('q');
126	  if (pre) { q.value = pre; q.dispatchEvent(new Event('input')); }
127	})();
