485	type El = ReactElement<Record<string, unknown> & { children?: ReactNode }>;
486	const kids = (n: ReactNode): ReactNode[] => (Array.isArray(n) ? n.flatMap((x) => kids(x as ReactNode)) : n == null ? [] : [n]);
487	
488	export function toHtml(node: ReactNode): string {
489	  if (node == null || typeof node === "boolean") return "";
490	  if (typeof node === "string" || typeof node === "number") return esc(String(node));
491	  if (Array.isArray(node)) return node.map(toHtml).join("");
492	  if (!isValidElement(node)) throw new Error("nxm tools: unsupported node in live tool content");
493	  const el = node as El;
494	  const inner = toHtml(el.props.children as ReactNode);
495	  if (el.type === Fragment) return inner;
496	  const href = typeof el.props.href === "string" ? el.props.href : null;
497	  if (typeof el.type === "string") {
498	    if (!TAGS.has(el.type)) throw new Error(`nxm tools: <${el.type}> in live tool content`);
499	    if (el.type === "br") return "<br>";
500	    if (el.type === "a") return `<a href="${esc(stagedHref(href ?? "#"))}"${el.props.target ? ` target="_blank" rel="noopener noreferrer"` : ""}>${inner}</a>`;
501	    return `<${el.type}>${inner}</${el.type}>`;
502	  }
503	  // next/link (a client reference on the server): any component with an href
504	  if (href) return `<a href="${esc(stagedHref(href))}">${inner}</a>`;
505	  throw new Error("nxm tools: unsupported component in live tool content");
506	}
