508	/** Plain text of a node (headings). */
509	export function toText(node: ReactNode): string {
510	  return toHtml(node).replace(/<[^>]+>/g, "").replace(/&#39;/g, "'").replace(/&#34;/g, '"').replace(/&#38;/g, "&").replace(/&#60;/g, "<").replace(/&#62;/g, ">").trim();
511	}
512	
513	/** Depth-first walk over a live page's element tree (through components'
514	 *  children props — nothing is rendered). */
515	function walk(node: ReactNode, visit: (el: El, parent: El | null) => void, parent: El | null = null) {
516	  for (const n of kids(node)) {
517	    if (!isValidElement(n)) continue;
518	    const el = n as El;
519	    visit(el, parent);
520	    walk(el.props.children as ReactNode, visit, el);
521	  }
522	}
