}) {
  return (
    <div className="rounded-xl border border-white/[0.07] bg-navy-950/50 p-4">
      {(title || action) && (
        <div className="mb-3 flex items-center justify-between gap-3">
          {title && <p className="section-label">{title}</p>}
          {action}
        </div>
      )}
      {children}
    </div>
  );
}

