const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;

export function DnsTool() {
  const [domain, setDomain] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [records, setRecords] = useState<Record<string, string[]> | null>(null);
  const [host, setHost] = useState("");

  async function run(e: React.FormEvent) {
    e.preventDefault();
    if (!domain.trim()) return;
    setLoading(true);
    setError("");
    setRecords(null);
    try {
      const res = await fetch("/api/tools/dns", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ domain }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Lookup failed.");
      setRecords(data.records);
      setHost(data.host);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Lookup failed.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-5">
      <form onSubmit={run} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Domain name" hint="Resolves A, AAAA, MX, TXT, NS, CNAME and SOA records.">
            <input
              className="input"
              placeholder="example.com"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit">
          Resolve
        </RunButton>
      </form>

      <ErrorNote>{error}</ErrorNote>

      {records && (
        <div className="space-y-3">
          {TYPES.map((t) => {
            const rows = records[t] ?? [];
            if (!rows.length) return null;
            return (
              <ResultCard key={t} title={`${t} · ${host}`}>
                <div className="space-y-1 font-mono text-[13px] text-slate-200">
                  {rows.map((r, i) => (
                    <div key={i} className="whitespace-pre-wrap break-words">
                      {r}
                    </div>
                  ))}
                </div>
              </ResultCard>
            );
          })}
          {TYPES.every((t) => !(records[t] ?? []).length) && (
            <p className="text-sm text-slate-500">No records found.</p>
          )}
        </div>
      )}
    </div>
  );
}
