const ALGOS = ["SHA-1", "SHA-256", "SHA-384", "SHA-512"] as const;
type Algo = (typeof ALGOS)[number];

function toHex(buf: ArrayBuffer): string {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function HashGeneratorTool() {
  const [input, setInput] = useState("");
  const [hashes, setHashes] = useState<Record<Algo, string>>({
    "SHA-1": "",
    "SHA-256": "",
    "SHA-384": "",
    "SHA-512": "",
  });

  useEffect(() => {
    let alive = true;
    if (!input) {
      setHashes({ "SHA-1": "", "SHA-256": "", "SHA-384": "", "SHA-512": "" });
      return;
    }
    const data = new TextEncoder().encode(input);
    Promise.all(ALGOS.map((a) => crypto.subtle.digest(a, data).then((d) => [a, toHex(d)] as const))).then((pairs) => {
      if (!alive) return;
      const next = {} as Record<Algo, string>;
      for (const [a, h] of pairs) next[a] = h;
      setHashes(next);
    });
    return () => {
      alive = false;
    };
  }, [input]);

  return (
    <div className="space-y-4">
      <div>
        <span className="label">Text to hash</span>
        <textarea
          className="input min-h-[100px] font-mono"
          placeholder="Type or paste anything…"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          spellCheck={false}
        />
      </div>

      <div className="space-y-3">
        {ALGOS.map((a) => (
          <div key={a} className="rounded-xl border border-white/[0.07] bg-navy-950/70 p-3">
            <div className="mb-1.5 flex items-center justify-between">
              <span className="section-label">{a}</span>
