            <p className="break-all font-mono text-[13px] text-slate-300">
              {hashes[a] || <span className="text-slate-600">—</span>}
            </p>
          </div>
        ))}
      </div>

      <p className="text-xs text-slate-500">
        Hashed locally with the Web Crypto API (<code className="kbd">crypto.subtle</code>). Your input never leaves the browser.
        Note: MD5 is intentionally omitted — it is cryptographically broken.
