"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { WORKLOADS, formatRam, parseCalcQuery, recommendPlan, requirementsFor, type PlanSpec, type Workload } from "@/lib/tools/server-sizing";
import type { CalcData, CalcPlan } from "../_data/tools-tool";

/**
 * The server size calculator on the new site, in the Aurora language.
 *
 * Same sizing model as the live tool (lib/tools/server-sizing: WORKLOADS,
 * requirementsFor, recommendPlan) — the difference is where it ends: every
 * recommendation is a REAL plan from the catalogue checkout sells (active
 * db.plan rows, and for games the family's active db.gamePlan tiers), with its
 * real price and a deploy link built by lib/deploy-intent's deployHref. The
 * page loader (app/nxm/_data/tools-tool.ts) puts that catalogue in
 * <script id="nxm-data">; nothing here is a snapshot.
 */
const GROUPS: Workload["group"][] = ["Game servers", "Web & apps", "Bots & self-hosting"];
const d = (n: number) => `$${n.toFixed(2)}`;

function readData(): CalcData["calc"] | null {
  try {
    const raw = document.getElementById("nxm-data")?.textContent;
    const v = raw ? (JSON.parse(raw) as CalcData) : null;
    return v?.calc?.vps?.length ? v.calc : null;
  } catch {
    return null;
  }
}

/** Smallest managed tier that meets the requirement, or null when none does. */
function fitTier(tiers: CalcPlan[], ramMB: number, cpu: number) {
  const byRam = [...tiers].sort((a, b) => a.ramMB - b.ramMB || a.cpu - b.cpu);
  return byRam.find((t) => t.ramMB >= ramMB && t.cpu >= cpu) ?? byRam.find((t) => t.ramMB >= ramMB) ?? null;
}

function Price({ p }: { p: CalcPlan }) {
  return p.intro != null ? (
    <div className="sc-price">
      <p><b>{d(p.intro)}</b><s>{d(p.price)}</s><span>/mo, {p.introSpan}</span></p>
      <small>Then {d(p.price)} a month</small>
    </div>
  ) : (
    <div className="sc-price">
      <p><b>{d(p.price)}</b><span>/mo</span></p>
      <small>&nbsp;</small>
    </div>
  );
}

function PlanCard({ kind, tag, plan, specs, deployLabel, rec }: { kind: string; tag: string; plan: CalcPlan; specs: string; deployLabel: string; rec: boolean }) {
  return (
    <article className={`sc-plan${rec ? " rec" : ""}`}>
      <span className="sc-tag">{tag}</span>
      <small className="sc-kind">{kind}</small>
      <h3>{plan.name}</h3>
      <p className="sc-specs">{specs}</p>
      <Price p={plan} />
      <a className={rec ? "nxm-btn au-hov" : "nxm-glassbtn"} href={plan.href}>
        <span className="nxm-bt">{deployLabel}</span>
        {rec && <span className="nxm-arw" aria-hidden="true">→</span>}
      </a>
    </article>
  );
}

export function ToolSizeCalculator() {
  const [data] = useState(readData);
  const [group, setGroup] = useState<Workload["group"]>(GROUPS[0]);
  const [workloadId, setWorkloadId] = useState(WORKLOADS[0].id);
  const workload = WORKLOADS.find((w) => w.id === workloadId) ?? WORKLOADS[0];
  const [scale, setScale] = useState<number>(workload.scaleDefault ?? 10);

  // deep link: /tools/server-size-calculator?workload=valheim&players=10 (applied after mount, so SSR markup is unchanged)
  useEffect(() => {
    const q = parseCalcQuery(location.search);
    const w = q && WORKLOADS.find((x) => x.id === q.workloadId);
    if (q && w) { setGroup(w.group); setWorkloadId(w.id); setScale(q.scale); }
  }, []);

  const segRef = useRef<HTMLDivElement>(null);
  const [pill, setPill] = useState<{ x: number; w: number } | null>(null);
  useLayoutEffect(() => {
    const place = () => {
      const b = segRef.current?.querySelector<HTMLButtonElement>('button[aria-pressed="true"]');
      if (b) setPill({ x: b.offsetLeft, w: b.offsetWidth });
    };
    place();
    addEventListener("resize", place);
    return () => removeEventListener("resize", place);
  }, [group]);

  function pickWorkload(id: string) {
    const w = WORKLOADS.find((x) => x.id === id) ?? WORKLOADS[0];
    setWorkloadId(id);
    setScale(w.scaleDefault ?? 10);
  }
  function pickGroup(g: Workload["group"]) {
    setGroup(g);
    const first = WORKLOADS.find((w) => w.group === g);
    if (first && workload.group !== g) pickWorkload(first.id);
  }

  const result = useMemo(() => {
    if (!data) return null;
    const req = requirementsFor(workload, scale);
    const specs: PlanSpec[] = data.vps.map((p) => ({ slug: p.id, name: p.name, cpuCores: p.cpu, ramMB: p.ramMB, diskGB: p.disk, priceCents: Math.round(p.price * 100) }));
    const vpsRec = recommendPlan(workload, scale, specs);
    const vps = vpsRec.plan ? data.vps.find((p) => p.id === vpsRec.plan!.slug) ?? null : null;
    const game = data.tiers[workload.id];
    const fit = game ? fitTier(game.tiers, req.ramMB, req.cpuCores) : null;
    const top = game ? [...game.tiers].sort((a, b) => b.ramMB - a.ramMB)[0] : null;
    const notes = [...vpsRec.notes];
    // no managed tier is big enough: when a Cloud VPS is, that is the pick;
    // when nothing is, show the closest of both and say so plainly
    const tier = fit ?? (vpsRec.exceedsCatalog ? top : null);
    if (game && !fit && top) {
      notes.unshift(vpsRec.exceedsCatalog
        ? `This wants more than our largest managed ${workload.label} tier (${top.name}, ${formatRam(top.ramMB)}).`
        : `This wants more than our largest managed ${workload.label} tier (${top.name}, ${formatRam(top.ramMB)}), so the pick is a Cloud VPS with the headroom.`);
    }
    if (tier && req.storageGB > tier.disk) notes.push(`You'll want about ${req.storageGB} GB of storage — more than the ${tier.name} tier's ${tier.disk} GB.`);
    return { req, vps, vpsExceeds: vpsRec.exceedsCatalog, tier, tierExceeds: !fit, notes };
  }, [data, workload, scale]);

  if (!data || !result) {
    return <p className="sc-err">The plan catalogue couldn&apos;t be loaded, so there&apos;s nothing honest to recommend right now. Please reload the page.</p>;
  }

  const max = workload.scaleMax ?? 100;
  const f = max > 1 ? (scale - 1) / (max - 1) : 0;
  const unit = workload.scale === "players" ? "players" : workload.scaleLabel?.toLowerCase() ?? "";
  const { req, vps, tier, notes } = result;
  const spec = (p: CalcPlan) => `${p.cpu} vCPU · ${formatRam(p.ramMB)} RAM · ${p.disk} GB NVMe${p.slots ? ` · ${p.slots} slots` : ""}`;

  return (
    <div className="sc">
      <div className="sc-step">
        <span className="sc-lab">1 · What are you hosting?</span>
        <div className="sc-seg" ref={segRef} role="group" aria-label="Workload type">
          {pill && <i className="pill" aria-hidden="true" style={{ width: pill.w, transform: `translateX(${pill.x - 4}px)` }} />}
          {GROUPS.map((g) => (
            <button key={g} type="button" aria-pressed={g === group} onClick={() => pickGroup(g)}>{g}</button>
          ))}
        </div>
        <div className="sc-chips" role="group" aria-label={group}>
          {WORKLOADS.filter((w) => w.group === group).map((w) => (
            <button key={w.id} type="button" className="sc-chip" aria-pressed={w.id === workloadId} onClick={() => pickWorkload(w.id)}>{w.label}</button>
          ))}
        </div>
      </div>

      <div className="sc-step">
        <span className="sc-lab">2 · {workload.scale !== "none" ? workload.scaleLabel ?? "Scale" : "Scale"}</span>
        {workload.scale !== "none" ? (
          <div className="sc-scale">
            <div className="au-range sc-range" style={{ ["--f" as string]: f }}>
              <span className="au-bub">{scale.toLocaleString()}</span>
              <input
                type="range" data-au min={1} max={max} value={scale}
                aria-label={workload.scaleLabel ?? "Scale"}
                style={{ ["--p" as string]: `${f * 100}%` }}
                onChange={(e) => setScale(Number(e.target.value))}
              />
            </div>
            <p className="sc-val"><b>{scale.toLocaleString()}</b> {unit}</p>
          </div>
        ) : (
          <p className="sc-val sc-none">Sized for a typical single instance</p>
        )}
        <p className="sc-hint">{workload.hint}</p>
      </div>

      <div className="sc-step">
        <span className="sc-lab">3 · Recommended specs</span>
        <div className="sc-req">
          <div><b>{formatRam(req.ramMB)}</b><small>RAM</small></div>
          <div><b>{req.cpuCores}</b><small>vCPU</small></div>
          <div><b>{req.storageGB} GB</b><small>Storage</small></div>
        </div>
      </div>

      <div className="sc-plans">
        {tier && (
          <PlanCard rec={!result.tierExceeds} kind={`Managed ${workload.label} server`} tag={result.tierExceeds ? "Closest managed tier" : "Recommended"} plan={tier} specs={spec(tier)} deployLabel="Deploy this server" />
        )}
        {vps && (
          <PlanCard
            rec={!tier}
            kind="Cloud VPS, full root"
            tag={result.vpsExceeds ? "Closest plan" : tier ? "Or self-manage it" : "Recommended"}
            plan={vps}
            specs={spec(vps)}
            deployLabel={`Deploy ${vps.name}`}
          />
        )}
      </div>

      {notes.length > 0 && (
        <ul className="sc-notes">{notes.map((n, i) => <li key={i}>{n}</li>)}</ul>
      )}

      <div className="sc-foot">
        <p>
          These are starting-point recommendations from real per-workload requirements and our live plan lineup. Actual
          needs vary with mods, plugins, traffic spikes and background jobs — full root access means you can resize any time.
        </p>
        <div className="sc-links">
          <a href={data.product[workload.id]}>{workload.productLabel} <span aria-hidden="true">→</span></a>
          <a href={data.pricing}>Compare all plans <span aria-hidden="true">→</span></a>
        </div>
      </div>
    </div>
  );
}
