/**
 * Plain-text renderings of the free tools' results, for their "Copy" buttons.
 * Pure (no DOM, no React) so the exact clipboard text is unit-tested
 * (test/tools-result-text.test.ts) and shared by every tool component.
 */

/** "key: value" lines; null/empty values are skipped. Keys are padded so the
 *  values line up when pasted into a terminal or a ticket. */
export function kvText(rows: [string, string | number | null | undefined][]): string {
  const kept = rows.filter(([, v]) => v !== null && v !== undefined && String(v).trim() !== "");
  const w = Math.max(0, ...kept.map(([k]) => k.length));
  return kept.map(([k, v]) => `${(k + ":").padEnd(w + 1)} ${String(v)}`).join("\n");
}

/** DNS records grouped by type, in the order given, as zone-file-ish lines. */
export function dnsText(host: string, records: Record<string, string[]>, types: readonly string[]): string {
  const lines: string[] = [];
  for (const t of types) for (const r of records[t] ?? []) lines.push(`${host}\t${t}\t${r}`);
  return lines.join("\n");
}

/** Number of records across the given types. */
export function dnsCount(records: Record<string, string[]>, types: readonly string[]): number {
  return types.reduce((n, t) => n + (records[t]?.length ?? 0), 0);
