"use client";

import { useState } from "react";

/**
 * Shared UI atoms for the interactive free-tool components. All client-side.
 *
 * Every atom carries a `tl-*` hook class next to its Tailwind classes: the
 * rollback marketing site (app/(marketing)/tools) renders the Tailwind look,
 * and the live NXM site restyles the same markup through CSS scoped to
 * `.tt-app` (tools/nxm/native/tools-app/page.css). Keep both working.
 */

export function CopyButton({
  value,
  label = "Copy",
  className = "",
  ariaLabel,
}: {
  value: string;
  label?: string;
  className?: string;
  /** what is being copied, for screen readers ("Copy SHA-256 hash") */
  ariaLabel?: string;
}) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  return (
    <button
      type="button"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(value);
          setState("copied");
        } catch {
          setState("failed"); // clipboard blocked (insecure context, permissions)
        }
        setTimeout(() => setState("idle"), 1600);
      }}
      className={`btn-secondary tl-copy px-3 py-1.5 text-xs ${className}`}
      data-state={state}
      disabled={!value}
      aria-label={state === "idle" ? ariaLabel : undefined}
      aria-live="polite"
    >
      <svg className="tl-copy-ic" viewBox="0 0 24 24" width="14" height="14" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        {state === "copied" ? <path d="M5 12.5l4.5 4.5L19 7.5" /> : <><rect x="8" y="8" width="12" height="12" rx="2.5" /><path d="M16 8V6.5A2.5 2.5 0 0 0 13.5 4h-7A2.5 2.5 0 0 0 4 6.5v7A2.5 2.5 0 0 0 6.5 16H8" /></>}
      </svg>
      {state === "copied" ? "Copied" : state === "failed" ? "Press Ctrl+C" : label}
    </button>
  );
}

export function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: React.ReactNode;
}) {
  return (
    <label className="tl-field block">
      <span className="label">{label}</span>
      {children}
      {hint && <span className="tl-hint mt-1 block text-xs text-slate-500">{hint}</span>}
    </label>
  );
}

export function ErrorNote({ children }: { children: React.ReactNode }) {
  if (!children) return null;
  return (
    <div role="alert" className="tl-err rounded-xl border border-red-500/25 bg-red-500/10 px-4 py-3 text-sm text-red-300">
      {children}
    </div>
  );
}

export function ResultCard({
  title,
  action,
  children,
}: {
  title?: string;
  action?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div className="tl-result rounded-xl border border-white/[0.07] bg-navy-950/50 p-4">
      {(title || action) && (
        <div className="tl-result-h mb-3 flex items-center justify-between gap-3">
          {title && <p className="section-label min-w-0 break-words">{title}</p>}
          {action}
        </div>
      )}
      {children}
    </div>
  );
}

/** Key/value grid for network results. A row's optional third item is the
 *  plain text its own copy button puts on the clipboard. */
export function KeyValue({ rows }: { rows: ([string, React.ReactNode] | [string, React.ReactNode, string | null | undefined])[] }) {
  return (
    <dl className="tl-kv grid grid-cols-1 gap-x-6 gap-y-2 sm:grid-cols-[max-content_1fr]">
      {rows.map(([k, v, copy], i) => (
        <div key={i} className="contents">
          <dt className="text-xs font-medium uppercase tracking-wide text-slate-500 sm:pt-0.5">{k}</dt>
          <dd className="flex min-w-0 items-start justify-between gap-3 break-words text-sm text-slate-200">
            <span className="min-w-0 break-words">{v ?? <span className="text-slate-600">—</span>}</span>
            {copy ? <CopyButton value={copy} className="tl-copy--sm shrink-0" ariaLabel={`Copy ${k.toLowerCase()}`} /> : null}
          </dd>
        </div>
      ))}
    </dl>
  );
}

/** Monospace preformatted output with a copy button. */
export function CodeOutput({ text, maxHeight = "22rem", label }: { text: string; maxHeight?: string; label?: string }) {
  return (
    <div className="tl-code relative">
      <div className="absolute right-2 top-2 z-10">
        <CopyButton value={text} ariaLabel={label ? `Copy ${label}` : undefined} />
      </div>
      <pre
        className="overflow-auto rounded-xl border border-white/[0.07] bg-navy-950/70 p-4 pr-16 font-mono text-[13px] leading-relaxed text-slate-300"
        style={{ maxHeight }}
        tabIndex={0}
      >
        {text}
      </pre>
    </div>
  );
}

export function RunButton({
  loading,
  children = "Run",
  ...rest
}: React.ButtonHTMLAttributes<HTMLButtonElement> & { loading?: boolean }) {
  return (
    <button {...rest} className="btn-primary tl-run px-5 py-2.5" disabled={loading || rest.disabled} aria-busy={loading || undefined}>
      {loading && <span className="tl-spin" aria-hidden="true" />}
      {loading ? "Working…" : children}
    </button>
  );
}

/** One-click sample inputs ("Try: nxeon.cloud github.com …"). */
export function Examples({
  items,
  onPick,
  label = "Try",
  disabled,
}: {
  items: { label: string; value?: string; title?: string }[];
  onPick: (value: string) => void;
  label?: string;
  disabled?: boolean;
}) {
  return (
    <div className="tl-ex flex flex-wrap items-center gap-2" role="group" aria-label={`${label}: example inputs`}>
      <span className="tl-ex-l text-xs font-medium text-slate-500">{label}</span>
      {items.map((it) => (
        <button
          key={it.label}
          type="button"
          disabled={disabled}
          title={it.title}
          onClick={() => onPick(it.value ?? it.label)}
          className="tl-chip rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 font-mono text-xs text-slate-400 transition-colors hover:border-brand-500/30 hover:text-white disabled:opacity-50"
        >
          {it.label}
        </button>
      ))}
    </div>
  );
}

/** What the result area says before the first run. */
export function EmptyState({ title, children }: { title: string; children?: React.ReactNode }) {
  return (
    <div className="tl-empty rounded-xl border border-dashed border-white/10 px-4 py-6 text-center">
      <p className="text-sm font-medium text-slate-300">{title}</p>
      {children && <p className="mt-1 text-xs leading-relaxed text-slate-500">{children}</p>}
    </div>
  );
}

/** Placeholder rows while a live check runs. */
export function LoadingRows({ label, rows = 3 }: { label: string; rows?: number }) {
  return (
    <div className="tl-loading space-y-2" role="status" aria-live="polite">
      <p className="flex items-center gap-2 text-sm text-slate-400">
        <span className="tl-spin" aria-hidden="true" />
        {label}
      </p>
      {Array.from({ length: rows }).map((_, i) => (
        <div key={i} className="nx-skel h-10 rounded-xl bg-white/[0.04]" />
      ))}
    </div>
  );
}

/** A coloured status pill (ok = green, warn = amber, bad = red, info = blue). */
export function StatusPill({ tone, children }: { tone: "ok" | "warn" | "bad" | "info"; children: React.ReactNode }) {
  const cls = {
    ok: "border-emerald-500/30 bg-emerald-500/10 text-emerald-300",
    warn: "border-amber-500/30 bg-amber-500/10 text-amber-300",
    bad: "border-red-500/30 bg-red-500/10 text-red-300",
    info: "border-blue-500/30 bg-blue-500/10 text-blue-300",
  }[tone];
  return (
    <span className={`tl-pill inline-flex items-center gap-2 rounded-full border px-3 py-1 text-sm font-semibold ${cls}`} data-tone={tone}>
      <span className="tl-pill-d h-2 w-2 rounded-full bg-current" aria-hidden="true" />
      {children}
    </span>
  );
}

/** Save text as a file (config generators). */
export function DownloadButton({ text, filename, label = "Download" }: { text: string; filename: string; label?: string }) {
  return (
    <button
      type="button"
      className="btn-secondary tl-dl px-3 py-1.5 text-xs"
      disabled={!text}
      onClick={() => {
        const url = URL.createObjectURL(new Blob([text], { type: "text/plain;charset=utf-8" }));
        const a = document.createElement("a");
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      }}
    >
      <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 4v11m0 0l-4.5-4.5M12 15l4.5-4.5M5 19.5h14" /></svg>
      {label}
    </button>
  );
}

