"use client";

import { useState } from "react";
import { CopyButton, EmptyState, ErrorNote, Examples, Field, LoadingRows, ResultCard, RunButton } from "./ui";
import { dnsCount, dnsText } from "@/lib/tools/result-text";

const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;
const EXAMPLES = [{ label: "nxeon.cloud" }, { label: "github.com" }, { label: "gmail.com", title: "A domain with MX + SPF records" }];

export function DnsTool() {
  const [domain, setDomain] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [records, setRecords] = useState<Record<string, string[]> | null>(null);
  const [host, setHost] = useState("");

  async function lookup(value: string) {
    if (!value.trim() || loading) return;
    setLoading(true);
    setError("");
    setRecords(null);
    try {
      const res = await fetch("/api/tools/dns", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ domain: value }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Lookup failed.");
      setRecords(data.records);
      setHost(data.host);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Lookup failed.");
    } finally {
      setLoading(false);
    }
  }

  const total = records ? dnsCount(records, TYPES) : 0;

  return (
    <div className="space-y-5">
      <form onSubmit={(e) => { e.preventDefault(); void lookup(domain); }} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Domain name" hint="Resolves A, AAAA, MX, TXT, NS, CNAME and SOA records.">
            <input
              className="input"
              placeholder="example.com"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              enterKeyHint="search"
              inputMode="url"
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit" disabled={!domain.trim()}>
          Resolve
        </RunButton>
      </form>

      <Examples items={EXAMPLES} disabled={loading} onPick={(v) => { setDomain(v); void lookup(v); }} />

      <ErrorNote>{error}</ErrorNote>

      <div aria-live="polite" className="space-y-3">
        {loading && <LoadingRows label="Querying all seven record types…" />}

        {!loading && !records && !error && (
          <EmptyState title="Records appear here">All seven record types come back from a single query, grouped by type.</EmptyState>
        )}

        {records && (
          <>
            <div className="tl-sum flex flex-wrap items-center justify-between gap-3">
              <p className="text-sm text-slate-400">
                <b className="text-white">{total}</b> record{total === 1 ? "" : "s"} for <span className="font-mono text-slate-200">{host}</span>
              </p>
              {total > 0 && <CopyButton value={dnsText(host, records, TYPES)} label="Copy all records" />}
            </div>
            {TYPES.map((t) => {
              const rows = records[t] ?? [];
              if (!rows.length) return null;
              return (
                <ResultCard key={t} title={`${t} · ${rows.length}`} action={<CopyButton value={rows.join("\n")} ariaLabel={`Copy ${t} records`} />}>
                  <div className="space-y-1 font-mono text-[13px] text-slate-200">
                    {rows.map((r, i) => (
                      <div key={i} className="whitespace-pre-wrap break-words">
                        {r}
                      </div>
                    ))}
                  </div>
                </ResultCard>
              );
            })}
            {total === 0 && (
              <EmptyState title="No records found">The domain answered, but publishes none of these record types. Check the spelling, or whether it is registered.</EmptyState>
            )}
          </>
        )}
      </div>
    </div>
  );
}

