import { kvText } from "@/lib/tools/result-text";

type WhoisResult = {
  host: string;
  server: string;
  summary: {
    registrar: string | null;
    created: string | null;
    updated: string | null;
    expires: string | null;
    status: string[];
    nameservers: string[];
  };
  raw: string;
};

const EXAMPLES = [{ label: "nxeon.cloud" }, { label: "wikipedia.org" }, { label: "github.com" }];

export function WhoisTool() {
  const [domain, setDomain] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<WhoisResult | null>(null);

  async function lookup(value: string) {
    if (!value.trim() || loading) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/whois", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ domain: value }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Lookup failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Lookup failed.");
    } finally {
      setLoading(false);
    }
  }

  const s = result?.summary;
  const summaryText = result && s
    ? kvText([
        ["Domain", result.host],
        ["Registrar", s.registrar],
        ["Created", s.created],
        ["Updated", s.updated],
        ["Expires", s.expires],
        ["Status", s.status.join(", ")],
        ["Nameservers", s.nameservers.join(", ")],
        ["WHOIS server", result.server],
      ])
    : "";

  return (
    <div className="space-y-5">
      <form onSubmit={(e) => { e.preventDefault(); void lookup(domain); }} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Domain name" hint="Registry & registrar WHOIS via IANA referral.">
            <input
              className="input"
              placeholder="example.com"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              enterKeyHint="search"
              inputMode="url"
            />
          </Field>
