      <ErrorNote>{error}</ErrorNote>

      <div aria-live="polite" className="space-y-4">
        {loading && <LoadingRows label="Asking IANA for the registry, then the registrar…" rows={4} />}

        {!loading && !result && !error && (
          <EmptyState title="Registration details appear here">Registrar, key dates, status codes and nameservers, plus the raw WHOIS response.</EmptyState>
        )}

        {result && s && (
          <>
            <ResultCard title={`WHOIS · ${result.host}`} action={<CopyButton value={summaryText} label="Copy summary" />}>
              <KeyValue
                rows={[
                  ["Registrar", s.registrar, s.registrar],
                  ["Created", s.created, s.created],
                  ["Updated", s.updated, s.updated],
                  ["Expires", s.expires, s.expires],
                  ["Status", s.status.length ? s.status.join(", ") : null],
                  [
                    "Nameservers",
                    s.nameservers.length ? (
                      <span className="flex flex-col gap-0.5 font-mono text-[13px]">
                        {s.nameservers.map((n) => (
                          <span key={n}>{n}</span>
                        ))}
                      </span>
                    ) : null,
                    s.nameservers.join("\n"),
                  ],
                  ["WHOIS server", <span className="font-mono text-[13px]">{result.server}</span>],
                ]}
              />
            </ResultCard>
            <ResultCard title="Raw response">
              <CodeOutput text={result.raw} label="raw WHOIS response" />
            </ResultCard>
          </>
        )}
      </div>
    </div>
  );
}

