"use client";

import { useState } from "react";
import { CopyButton, EmptyState, ErrorNote, Examples, Field, KeyValue, LoadingRows, ResultCard, RunButton, StatusPill } from "./ui";
import { hostPort, kvText, splitHostPort } from "@/lib/tools/result-text";

const PRESETS = [
  { label: "SSH · 22", port: 22 },
  { label: "HTTP · 80", port: 80 },
  { label: "HTTPS · 443", port: 443 },
  { label: "MySQL · 3306", port: 3306 },
  { label: "Postgres · 5432", port: 5432 },
  { label: "Minecraft · 25565", port: 25565 },
];
const EXAMPLES = [{ label: "nxeon.cloud:443" }, { label: "github.com:22" }, { label: "1.1.1.1:53", title: "Cloudflare DNS over TCP" }];

type Result = {
  host: string;
  ip: string;
  port: number;
  service: string | null;
  open: boolean;
  latencyMs: number | null;
};

export function PortCheckerTool() {
  const [host, setHost] = useState("");
  const [port, setPort] = useState("443");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<Result | null>(null);

  async function check(h: string, p: string) {
    if (!h.trim() || loading) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/port-checker", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ host: h, port: Number(p) }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Check failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Check failed.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-5">
      <form onSubmit={(e) => { e.preventDefault(); void check(host, port); }} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Host or IP">
            <input
              className="input"
              placeholder="example.com"
              value={host}
              onChange={(e) => {
                // pasting "host:port" fills both fields
                const v = e.target.value;
                const hp = /^[^:\s]+:\d{1,5}$/.test(v.trim()) ? splitHostPort(v) : null;
                if (hp) { setHost(hp.host); setPort(hp.port); } else setHost(v);
              }}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              enterKeyHint="go"
            />
          </Field>
        </div>
        <div className="w-full sm:w-32">
          <Field label="Port">
            <input
              className="input"
              inputMode="numeric"
              placeholder="443"
              value={port}
              onChange={(e) => setPort(e.target.value.replace(/[^0-9]/g, "").slice(0, 5))}
              enterKeyHint="go"
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit" disabled={!host.trim() || !port}>
          Check
        </RunButton>
      </form>

      <div className="tl-presets flex flex-wrap items-center gap-2" role="group" aria-label="Common ports">
        <span className="tl-ex-l text-xs font-medium text-slate-500">Port</span>
        {PRESETS.map((p) => (
          <button
            key={p.port}
            type="button"
            onClick={() => setPort(String(p.port))}
            aria-pressed={port === String(p.port)}
            className="tl-chip rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-xs text-slate-400 transition-colors hover:border-brand-500/30 hover:text-white"
          >
            {p.label}
          </button>
        ))}
      </div>
      <Examples
        items={EXAMPLES}
        disabled={loading}
        onPick={(v) => { const hp = splitHostPort(v); setHost(hp.host); setPort(hp.port); void check(hp.host, hp.port); }}
      />

      <ErrorNote>{error}</ErrorNote>

      <div aria-live="polite">
        {loading && <LoadingRows label={`Opening a TCP connection to port ${port}…`} rows={2} />}

        {!loading && !result && !error && (
          <EmptyState title="The result appears here">We try a TCP connection from our servers and report open or closed, the resolved IP and the round-trip time.</EmptyState>
        )}

        {result && (
          <ResultCard
            action={
              <CopyButton
                value={kvText([["Target", hostPort(result.host, result.port)], ["State", result.open ? "open" : "closed / filtered"], ["IP", result.ip], ["Service", result.service], ["Latency", result.latencyMs != null ? `${result.latencyMs} ms` : null]])}
                label="Copy result"
              />
            }
          >
            <div className="mb-3 flex items-center gap-2">
              <StatusPill tone={result.open ? "ok" : "bad"}>
                Port {result.port} is {result.open ? "OPEN" : "closed / filtered"}
              </StatusPill>
            </div>
            <KeyValue
              rows={[
                ["Host", result.host],
                ["Resolved IP", <span className="font-mono text-[13px]">{result.ip}</span>, result.ip],
                ["Service", result.service],
                ["Latency", result.latencyMs != null ? `${result.latencyMs} ms` : null],
              ]}
            />
            {!result.open && (
