"use client";

import { useState } from "react";
import { CopyButton, EmptyState, ErrorNote, Examples, Field, KeyValue, LoadingRows, ResultCard, RunButton, StatusPill } from "./ui";
import { kvText } from "@/lib/tools/result-text";

type Result = {
  host: string;
  subject: string | null;
  issuer: string | null;
  altNames: string[];
  validFrom: string;
  validTo: string;
  daysToExpiry: number;
  expired: boolean;
  valid: boolean;
  validationError: string | null;
  protocol: string | null;
  serialNumber: string | null;
  chain: { subject: string | null; issuer: string | null; validTo: string }[];
};

const EXAMPLES = [
  { label: "nxeon.cloud" },
  { label: "github.com" },
  { label: "expired.badssl.com", title: "A public test host that serves an expired certificate" },
];

function fmt(iso: string) {
  try {
    return new Date(iso).toUTCString();
  } catch {
    return iso;
  }
}

export function SslCheckerTool() {
  const [host, setHost] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<Result | null>(null);

  async function check(value: string) {
    if (!value.trim() || loading) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/ssl-checker", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ host: value }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Check failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Check failed.");
    } finally {
      setLoading(false);
    }
  }

  const expiryTone = !result
    ? ""
    : result.expired
      ? "text-red-300"
      : result.daysToExpiry < 14
        ? "text-amber-300"
        : "text-emerald-300";
  const ok = !!result && result.valid && !result.expired;

  return (
    <div className="space-y-5">
      <form onSubmit={(e) => { e.preventDefault(); void check(host); }} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Hostname" hint="Connects on port 443 and inspects the presented certificate.">
            <input
              className="input"
              placeholder="example.com"
              value={host}
              onChange={(e) => setHost(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              enterKeyHint="go"
              inputMode="url"
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit" disabled={!host.trim()}>
          Check SSL
        </RunButton>
      </form>

      <Examples items={EXAMPLES} disabled={loading} onPick={(v) => { setHost(v); void check(v); }} />

      <ErrorNote>{error}</ErrorNote>

      <div aria-live="polite" className="space-y-4">
        {loading && <LoadingRows label="Opening a TLS connection on port 443…" rows={3} />}

        {!loading && !result && !error && (
          <EmptyState title="The certificate report appears here">Validity, days to expiry, issuer, the names it covers and the full chain the server sends.</EmptyState>
        )}

        {result && (
          <>
            <ResultCard
              action={
                <CopyButton
                  label="Copy report"
                  value={kvText([
                    ["Host", result.host],
                    ["Status", ok ? "valid" : result.expired ? "expired" : "issue"],
                    ["Expires", `${fmt(result.validTo)} (${result.daysToExpiry} days)`],
                    ["Subject", result.subject],
                    ["Issuer", result.issuer],
                    ["Valid from", fmt(result.validFrom)],
                    ["Protocol", result.protocol],
                    ["Serial", result.serialNumber],
                    ["Validation", result.validationError],
                  ])}
                />
              }
            >
              <div className="mb-3 flex flex-wrap items-center gap-2">
                <StatusPill tone={ok ? "ok" : result.expired ? "bad" : "warn"}>
                  {ok ? "Certificate valid" : result.expired ? "Certificate expired" : "Certificate issue"}
                </StatusPill>
                <span className={`text-sm font-medium ${expiryTone}`}>
                  {result.expired
                    ? `Expired ${Math.abs(result.daysToExpiry)} days ago`
                    : `Expires in ${result.daysToExpiry} days`}
                </span>
              </div>
              <KeyValue
                rows={[
                  ["Subject", result.subject],
                  ["Issuer", result.issuer],
                  ["Valid from", fmt(result.validFrom)],
                  ["Valid to", fmt(result.validTo)],
                  ["Protocol", result.protocol],
                  ["Serial", result.serialNumber ? <span className="font-mono text-[12px]">{result.serialNumber}</span> : null, result.serialNumber],
                  ...(result.validationError
                    ? ([["Validation", <span className="text-amber-300">{result.validationError}</span>]] as [string, React.ReactNode][])
                    : []),
                ]}
              />
            </ResultCard>

            {result.altNames.length > 0 && (
              <ResultCard title={`Subject alternative names · ${result.altNames.length}`} action={<CopyButton value={result.altNames.join("\n")} ariaLabel="Copy subject alternative names" />}>
                <div className="flex flex-wrap gap-1.5">
                  {result.altNames.map((n) => (
                    <span key={n} className="tl-tag rounded-md border border-white/10 bg-white/[0.03] px-2 py-0.5 font-mono text-[12px] text-slate-300">
                      {n}
                    </span>
                  ))}
                </div>
              </ResultCard>
            )}

            {result.chain.length > 0 && (
              <ResultCard title="Certificate chain">
                <ol className="tl-chain space-y-2">
                  {result.chain.map((c, i) => (
                    <li key={i} className="flex gap-3 text-sm">
                      <span className="mt-0.5 text-xs text-slate-600">{i + 1}</span>
                      <div className="min-w-0 break-words">
                        <div className="text-slate-200">{c.subject ?? "—"}</div>
                        <div className="text-xs text-slate-500">Issued by {c.issuer ?? "—"}</div>
                      </div>
                    </li>
                  ))}
                </ol>
              </ResultCard>
            )}
          </>
        )}
      </div>
    </div>
  );
}

