"use client";

import { useState } from "react";
import { CopyButton, EmptyState, ErrorNote, Examples, Field, LoadingRows, ResultCard, RunButton, StatusPill } from "./ui";
import { headersText } from "@/lib/tools/result-text";

type Result = {
  url: string;
  status: number;
  statusText: string;
  redirect: string | null;
  headers: [string, string][];
};

const EXAMPLES = [
  { label: "https://nxeon.cloud" },
  { label: "http://github.com", title: "Shows a redirect to HTTPS" },
  { label: "https://example.com" },
];

export function HttpHeadersTool() {
  const [url, setUrl] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<Result | null>(null);

  async function fetchHeaders(value: string) {
    if (!value.trim() || loading) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/http-headers", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ url: value }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Request failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Request failed.");
    } finally {
      setLoading(false);
    }
  }

  const tone = !result ? "info" : result.status < 300 ? "ok" : result.status < 400 ? "info" : "bad";

  return (
    <div className="space-y-5">
      <form onSubmit={(e) => { e.preventDefault(); void fetchHeaders(url); }} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="URL" hint="Redirects are reported, not followed. https:// assumed if omitted.">
            <input
              className="input"
              placeholder="https://example.com"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              enterKeyHint="go"
              inputMode="url"
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit" disabled={!url.trim()}>
          Fetch headers
        </RunButton>
      </form>

      <Examples items={EXAMPLES} disabled={loading} onPick={(v) => { setUrl(v); void fetchHeaders(v); }} />

      <ErrorNote>{error}</ErrorNote>

      <div aria-live="polite">
        {loading && <LoadingRows label="Requesting the URL from our servers…" rows={4} />}

        {!loading && !result && !error && (
          <EmptyState title="The response appears here">Status code, any redirect target, and every response header the server sends.</EmptyState>
        )}

        {result && (
          <ResultCard title={result.url} action={<CopyButton value={headersText(result.status, result.statusText, result.headers)} label="Copy headers" />}>
            <div className="mb-3 flex flex-wrap items-center gap-2">
              <StatusPill tone={tone}>
                {result.status} {result.statusText}
              </StatusPill>
              {result.redirect && (
                <span className="min-w-0 break-all text-sm text-slate-400">
                  → <span className="font-mono text-[13px] text-slate-300">{result.redirect}</span>
                </span>
              )}
            </div>
            <div className="overflow-x-auto">
              <table className="tl-table w-full text-sm">
                <caption className="sr-only">Response headers ({result.headers.length})</caption>
                <tbody>
                  {result.headers.map(([k, v], i) => (
                    <tr key={i} className="border-t border-white/[0.05]">
                      <th scope="row" className="py-1.5 pr-4 text-left align-top font-mono text-[13px] font-normal text-brand-300">{k}</th>
                      <td className="py-1.5 align-top font-mono text-[13px] break-all text-slate-300">{v}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </ResultCard>
        )}
      </div>
    </div>
  );
}

