type Result = {
  ip: string;
  version: string;
  reverseDns: string | null;
  userAgent: string | null;
};

export function MyIpTool() {
  const [result, setResult] = useState<Result | null>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [origin, setOrigin] = useState("https://nxeon.cloud");

  useEffect(() => {
    if (typeof window !== "undefined") setOrigin(window.location.origin);
  }, []);

  const detect = useCallback((signal?: { alive: boolean }) => {
    setLoading(true);
    setError("");
    fetch("/api/tools/my-ip", { cache: "no-store" })
      .then((r) => r.json())
      .then((d) => {
        if (signal && !signal.alive) return;
        if (d.ok) setResult(d);
        else setError(d.error || "Could not detect your IP.");
      })
      .catch(() => (!signal || signal.alive) && setError("Could not detect your IP."))
      .finally(() => (!signal || signal.alive) && setLoading(false));
  }, []);

  useEffect(() => {
    const signal = { alive: true };
    detect(signal);
    return () => {
      signal.alive = false;
    };
  }, [detect]);

  const curl = `curl ${origin}/api/tools/my-ip`;

  return (
    <div className="space-y-5">
      <ErrorNote>{error}</ErrorNote>

      <div className="tl-hero rounded-2xl border border-brand-500/20 bg-gradient-to-br from-brand-500/10 to-accent-blue/5 p-6 text-center" aria-live="polite">
        <p className="section-label">Your public IP address</p>
        <p className="tl-big mt-2 break-all font-mono text-3xl font-bold text-white sm:text-4xl" aria-busy={loading || undefined}>
          {result ? result.ip : loading ? <span className="nx-skel mx-auto block h-10 w-64 max-w-full rounded-xl bg-white/[0.05]" aria-label="Detecting" /> : "—"}
        </p>
        <div className="mt-4 flex flex-wrap justify-center gap-2">
          {result && <CopyButton value={result.ip} label="Copy IP" />}
          <button type="button" onClick={() => detect()} disabled={loading} className="btn-secondary px-3 py-1.5 text-xs">
            {loading ? "Detecting…" : error ? "Try again" : "Refresh"}
          </button>
        </div>
      </div>

      {result && (
        <ResultCard title="Details">
          <KeyValue
            rows={[
              ["IP version", result.version],
              ["Reverse DNS", result.reverseDns ? <span className="font-mono text-[13px]">{result.reverseDns}</span> : "None", result.reverseDns],
              ["User agent", result.userAgent ? <span className="text-xs">{result.userAgent}</span> : null, result.userAgent],
            ]}
          />
        </ResultCard>
      )}

      <div className="tl-tip flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.07] bg-navy-950/50 px-4 py-3">
        <p className="min-w-0 text-xs text-slate-500">
          From a terminal, for JSON: <code className="kbd break-all">{curl}</code>
        </p>
        <CopyButton value={curl} label="Copy command" />
      </div>
    </div>
  );
}

