"use client";

import { useCallback, useEffect, useState } from "react";
import { CopyButton } from "./ui";

const SETS = {
  lower: "abcdefghijklmnopqrstuvwxyz",
  upper: "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
  digits: "0123456789",
  symbols: "!@#$%^&*()-_=+[]{};:,.<>?/",
};
const AMBIGUOUS = new Set("Il1O0o".split(""));
const LENGTHS = [12, 16, 20, 32, 64];

/** Cryptographically strong random integer in [0, max) with no modulo bias. */
function randInt(max: number): number {
  const limit = Math.floor(0xffffffff / max) * max;
  const buf = new Uint32Array(1);
  let x = 0;
  do {
    crypto.getRandomValues(buf);
    x = buf[0];
  } while (x >= limit);
  return x % max;
}

export function PasswordGeneratorTool() {
  const [length, setLength] = useState(20);
  const [opts, setOpts] = useState({ lower: true, upper: true, digits: true, symbols: true });
  const [noAmbiguous, setNoAmbiguous] = useState(false);
  const [password, setPassword] = useState("");

  const generate = useCallback(() => {
    let pool = "";
    const required: string[] = [];
    (Object.keys(SETS) as (keyof typeof SETS)[]).forEach((k) => {
      if (!opts[k]) return;
      let chars = SETS[k];
      if (noAmbiguous) chars = [...chars].filter((c) => !AMBIGUOUS.has(c)).join("");
      pool += chars;
      required.push(chars[randInt(chars.length)]);
    });
    if (!pool) {
      setPassword("");
      return;
    }
    const out: string[] = [...required];
    for (let i = out.length; i < length; i++) out.push(pool[randInt(pool.length)]);
    // Fisher–Yates shuffle so the required chars aren't always leading.
    for (let i = out.length - 1; i > 0; i--) {
      const j = randInt(i + 1);
      [out[i], out[j]] = [out[j], out[i]];
    }
    setPassword(out.slice(0, length).join(""));
  }, [length, opts, noAmbiguous]);

  useEffect(() => {
    generate();
  }, [generate]);

  // Rough entropy estimate for the strength meter.
  const poolSize = (Object.keys(SETS) as (keyof typeof SETS)[]).reduce(
    (n, k) => n + (opts[k] ? SETS[k].length : 0),
    0,
  );
  const entropy = poolSize > 0 ? Math.round(length * Math.log2(poolSize)) : 0;
  const strength = entropy >= 100 ? "Excellent" : entropy >= 75 ? "Strong" : entropy >= 50 ? "Fair" : "Weak";
  const strengthTone =
    entropy >= 75 ? "text-emerald-300" : entropy >= 50 ? "text-amber-300" : "text-red-300";
  const pct = Math.min(100, Math.round((entropy / 128) * 100));

  return (
    <div className="space-y-5">
      <div className="tl-out flex flex-col gap-2 sm:flex-row sm:items-stretch">
        <output
          className="tl-pw flex min-h-[56px] min-w-0 flex-1 items-center rounded-xl border border-white/10 bg-navy-950/70 px-4 py-3 font-mono text-lg text-white"
          aria-label="Generated password"
          aria-live="polite"
        >
          <span className="min-w-0 break-all">{password || <span className="text-slate-600">Select at least one character set</span>}</span>
        </output>
        <div className="tl-out-a grid grid-cols-2 gap-2 sm:flex sm:flex-col">
          <CopyButton value={password} className="h-full px-4 py-2 text-sm" ariaLabel="Copy password" />
          <button type="button" onClick={generate} className="btn-secondary tl-regen px-4 py-2 text-sm" disabled={!poolSize}>
            Regenerate
          </button>
        </div>
      </div>

      <div>
        <div className="mb-1 flex items-center justify-between text-sm">
          <span className="text-slate-400">Strength</span>
          <span className={strengthTone}>
            {strength} · ~{entropy} bits
          </span>
        </div>
        <div className="tl-meter h-2 overflow-hidden rounded-full bg-white/[0.06]" role="meter" aria-valuemin={0} aria-valuemax={128} aria-valuenow={Math.min(entropy, 128)} aria-label="Estimated entropy">
          <div
            className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-all"
            style={{ width: `${pct}%` }}
          />
        </div>
      </div>

      <div>
        <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
          <label htmlFor="pw-length" className="label mb-0">Length</label>
          <div className="flex flex-wrap items-center gap-1.5" role="group" aria-label="Length presets">
            {LENGTHS.map((n) => (
              <button
                key={n}
                type="button"
                aria-pressed={length === n}
                onClick={() => setLength(n)}
                className={`tl-chip rounded-full border px-2.5 py-0.5 font-mono text-xs transition-colors ${length === n ? "border-brand-500/50 bg-brand-500/15 text-brand-200" : "border-white/10 bg-white/[0.03] text-slate-400 hover:text-white"}`}
              >
                {n}
              </button>
            ))}
            <span className="ml-1 font-mono text-sm text-brand-300" aria-hidden="true">{length}</span>
          </div>
        </div>
        <input
          id="pw-length"
          type="range"
          min={6}
          max={64}
          value={length}
          onChange={(e) => setLength(Number(e.target.value))}
          className="w-full accent-brand-500"
        />
      </div>

      <fieldset className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        <legend className="sr-only">Character sets</legend>
        {(
          [
            ["lower", "a-z", "Lowercase"],
            ["upper", "A-Z", "Uppercase"],
            ["digits", "0-9", "Digits"],
            ["symbols", "!@#$", "Symbols"],
          ] as const
        ).map(([key, label, name]) => (
          <label
            key={key}
            className={`tl-opt flex cursor-pointer items-center gap-2 rounded-xl border px-3 py-2 text-sm transition-colors ${
              opts[key] ? "border-brand-500/40 bg-brand-500/10 text-white" : "border-white/10 bg-white/[0.02] text-slate-400"
            }`}
            title={name}
          >
            <input
              type="checkbox"
              className="accent-brand-500"
              checked={opts[key]}
              onChange={(e) => setOpts((o) => ({ ...o, [key]: e.target.checked }))}
              aria-label={name}
            />
            <span className="font-mono">{label}</span>
          </label>
        ))}
      </fieldset>

      <label className="flex cursor-pointer items-center gap-2 text-sm text-slate-400">
        <input
          type="checkbox"
          className="accent-brand-500"
          checked={noAmbiguous}
          onChange={(e) => setNoAmbiguous(e.target.checked)}
        />
        Exclude ambiguous characters (I, l, 1, O, 0)
      </label>

      <p className="text-xs text-slate-500">
        Generated locally in your browser with <code className="kbd">crypto.getRandomValues</code>. Nothing is sent to a server.
      </p>
    </div>
  );
}

