"use client";

import { useEffect, useState } from "react";
import { CopyButton, Examples } from "./ui";
import { kvText, utf8Bytes } from "@/lib/tools/result-text";

const ALGOS = ["SHA-1", "SHA-256", "SHA-384", "SHA-512"] as const;
type Algo = (typeof ALGOS)[number];
const EMPTY: Record<Algo, string> = { "SHA-1": "", "SHA-256": "", "SHA-384": "", "SHA-512": "" };
const EXAMPLES = [{ label: "hello world" }, { label: "The quick brown fox jumps over the lazy dog", title: "The classic test vector" }];

function toHex(buf: ArrayBuffer): string {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function HashGeneratorTool() {
  const [input, setInput] = useState("");
  const [upper, setUpper] = useState(false);
  const [hashes, setHashes] = useState<Record<Algo, string>>(EMPTY);

  useEffect(() => {
    let alive = true;
    if (!input) {
      setHashes(EMPTY);
      return;
    }
    const data = new TextEncoder().encode(input);
    Promise.all(ALGOS.map((a) => crypto.subtle.digest(a, data).then((d) => [a, toHex(d)] as const))).then((pairs) => {
      if (!alive) return;
      const next = {} as Record<Algo, string>;
      for (const [a, h] of pairs) next[a] = h;
      setHashes(next);
    });
    return () => {
      alive = false;
