"use client";

import { useState } from "react";
import { CopyButton, ErrorNote } from "./ui";
import { fmtBytes, utf8Bytes } from "@/lib/tools/result-text";

/** UTF-8 safe base64 using TextEncoder/Decoder. */
function encode(str: string): string {
  const bytes = new TextEncoder().encode(str);
  let bin = "";
  bytes.forEach((b) => (bin += String.fromCharCode(b)));
  return btoa(bin);
}
function decode(b64: string): string {
  const bin = atob(b64.trim());
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

const SAMPLE = { encode: "Hello, world! Grüße from Nxeon 👋", decode: "SGVsbG8sIHdvcmxkIQ==" };

export function Base64Tool() {
  const [mode, setMode] = useState<"encode" | "decode">("encode");
  const [input, setInput] = useState("");

  // Derive output and error purely from state — no render-phase setState.
  let output = "";
  let error = "";
  if (input) {
    try {
      output = mode === "encode" ? encode(input) : decode(input);
    } catch {
      if (mode === "decode") error = "Input is not valid Base64.";
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="tl-seg inline-flex rounded-xl border border-white/10 bg-white/[0.03] p-1" role="group" aria-label="Direction">
          {(["encode", "decode"] as const).map((m) => (
            <button
              key={m}
              type="button"
              onClick={() => setMode(m)}
              aria-pressed={mode === m}
              className={`rounded-lg px-4 py-1.5 text-sm font-medium capitalize transition-colors ${
                mode === m ? "bg-brand-500/20 text-white" : "text-slate-400 hover:text-white"
              }`}
            >
              {m}
            </button>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button type="button" className="btn-secondary px-3 py-1.5 text-xs" onClick={() => setInput(SAMPLE[mode])}>
            Load a sample
          </button>
          <button
            type="button"
            className="btn-secondary px-3 py-1.5 text-xs"
            disabled={!output}
            title="Use the result as the input and flip the direction"
            onClick={() => { setInput(output); setMode(mode === "encode" ? "decode" : "encode"); }}
          >
            ⇅ Swap
          </button>
          <button type="button" className="btn-secondary px-3 py-1.5 text-xs" disabled={!input} onClick={() => setInput("")}>
            Clear
          </button>
        </div>
      </div>

      <div>
        <div className="mb-1.5 flex items-center justify-between gap-2">
          <label htmlFor="b64-in" className="label mb-0">{mode === "encode" ? "Text to encode" : "Base64 to decode"}</label>
          {input && <span className="font-mono text-xs text-slate-500">{fmtBytes(utf8Bytes(input))}</span>}
        </div>
        <textarea
          id="b64-in"
          className="input min-h-[120px] font-mono"
          placeholder={mode === "encode" ? "Hello, world!" : "SGVsbG8sIHdvcmxkIQ=="}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          spellCheck={false}
        />
      </div>

      <ErrorNote>{error}</ErrorNote>

      <div>
        <div className="mb-1.5 flex items-center justify-between gap-2">
          <label htmlFor="b64-out" className="label mb-0">Result{output ? ` · ${fmtBytes(utf8Bytes(output))}` : ""}</label>
          <CopyButton value={output} ariaLabel="Copy result" />
        </div>
        <textarea
          id="b64-out"
          readOnly
          className="input min-h-[120px] font-mono text-slate-300"
          value={output}
          placeholder="The result appears here as you type"
        />
      </div>
    </div>
  );
}

