"use client";

import { useCallback, useEffect, useState } from "react";
import { CopyButton } from "./ui";

const COUNTS = [1, 5, 25, 100];

export function UuidGeneratorTool() {
  const [count, setCount] = useState(5);
  const [uppercase, setUppercase] = useState(false);
  const [hyphens, setHyphens] = useState(true);
  const [uuids, setUuids] = useState<string[]>([]);

  const generate = useCallback(() => {
    const n = Math.min(100, Math.max(1, count));
    const out: string[] = [];
    for (let i = 0; i < n; i++) {
      let u = crypto.randomUUID();
      if (!hyphens) u = u.replace(/-/g, "");
      if (uppercase) u = u.toUpperCase();
      out.push(u);
    }
    setUuids(out);
  }, [count, uppercase, hyphens]);

  useEffect(() => {
    generate();
  }, [generate]);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-end gap-3">
        <label className="block">
          <span className="label">How many</span>
          <input
            type="number"
            min={1}
            max={100}
            className="input w-28"
            value={count}
            onChange={(e) => setCount(Math.min(100, Number(e.target.value) || 1))}
          />
        </label>
        <div className="flex flex-wrap items-center gap-1.5 pb-2.5" role="group" aria-label="Quick counts">
          {COUNTS.map((n) => (
            <button
              key={n}
              type="button"
              aria-pressed={count === n}
              onClick={() => setCount(n)}
              className={`tl-chip rounded-full border px-2.5 py-0.5 font-mono text-xs transition-colors ${count === n ? "border-brand-500/50 bg-brand-500/15 text-brand-200" : "border-white/10 bg-white/[0.03] text-slate-400 hover:text-white"}`}
            >
              {n}
            </button>
          ))}
        </div>
        <label className="flex cursor-pointer items-center gap-2 pb-2.5 text-sm text-slate-400">
          <input type="checkbox" className="accent-brand-500" checked={uppercase} onChange={(e) => setUppercase(e.target.checked)} />
          Uppercase
        </label>
        <label className="flex cursor-pointer items-center gap-2 pb-2.5 text-sm text-slate-400">
          <input type="checkbox" className="accent-brand-500" checked={hyphens} onChange={(e) => setHyphens(e.target.checked)} />
          Hyphens
        </label>
        <div className="ml-auto flex flex-wrap gap-2">
          <CopyButton value={uuids.join("\n")} label={`Copy all ${uuids.length}`} className="px-4 py-2.5 text-sm" />
          <button type="button" onClick={generate} className="btn-primary px-4 py-2.5">
            Regenerate
          </button>
        </div>
      </div>

      <div className="tl-list max-h-[28rem] overflow-auto rounded-xl border border-white/[0.07] bg-navy-950/70 p-1" aria-live="polite">
        {uuids.map((u, i) => (
          <div key={i} className="flex items-center justify-between gap-3 rounded-lg px-3 py-2 hover:bg-white/[0.03]">
            <span className="min-w-0 break-all font-mono text-[13px] text-slate-200">{u}</span>
            <CopyButton value={u} className="shrink-0" ariaLabel={`Copy UUID ${i + 1}`} />
          </div>
        ))}
      </div>

      <p className="text-xs text-slate-500">Version 4 (random) UUIDs via <code className="kbd">crypto.randomUUID</code>, generated in your browser.</p>
    </div>
  );
}

