"use client";

import Link from "next/link";
import { useState } from "react";
import { CopyButton, EmptyState, ErrorNote, Examples, Field, KeyValue, LoadingRows, ResultCard, RunButton, StatusPill } from "./ui";
import { hostPort, splitHostPort } from "@/lib/tools/result-text";

type Result = {
  host: string;
  port: number;
  online: boolean;
  versionName?: string | null;
  protocol?: number | null;
  playersOnline?: number | null;
  playersMax?: number | null;
  sample?: string[];
  motd?: string;
  favicon?: boolean;
  latencyMs?: number;
};

const EXAMPLES = [{ label: "mc.hypixel.net" }, { label: "play.cubecraft.net" }];

export function MinecraftStatusTool() {
  const [host, setHost] = useState("");
  const [port, setPort] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<Result | null>(null);

  async function check(h: string, p: string) {
    if (!h.trim() || loading) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/mc-status", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ host: h, port: p.trim() ? Number(p) : undefined }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Check failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Check failed.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-5">
      <form onSubmit={(e) => { e.preventDefault(); void check(host, port); }} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Server address" hint="A domain or IP, e.g. play.hypixel.net. We'll follow SRV records automatically.">
            <input
              className="input"
              placeholder="play.example.net"
              value={host}
              onChange={(e) => {
                const v = e.target.value;
                const hp = /^[^:\s]+:\d{1,5}$/.test(v.trim()) ? splitHostPort(v) : null;
                if (hp) { setHost(hp.host); setPort(hp.port); } else setHost(v);
              }}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              enterKeyHint="go"
            />
          </Field>
        </div>
        <div className="w-full sm:w-32">
          <Field label="Port">
            <input
              className="input"
              inputMode="numeric"
              placeholder="25565"
              value={port}
              onChange={(e) => setPort(e.target.value.replace(/[^0-9]/g, "").slice(0, 5))}
              enterKeyHint="go"
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit" disabled={!host.trim()}>
          Check status
        </RunButton>
      </form>

      <Examples items={EXAMPLES} disabled={loading} onPick={(v) => { setHost(v); setPort(""); void check(v, ""); }} />

      <ErrorNote>{error}</ErrorNote>

      <div aria-live="polite">
        {loading && <LoadingRows label="Pinging the server (following SRV records)…" rows={2} />}

        {!loading && !result && !error && (
          <EmptyState title="Server status appears here">Online or offline, players, version, MOTD and ping, straight from the server&apos;s own status response.</EmptyState>
        )}

        {result && (
          <ResultCard action={<CopyButton value={hostPort(result.host, result.port)} label="Copy address" />}>
            <div className="mb-3 flex flex-wrap items-center gap-2">
              <StatusPill tone={result.online ? "ok" : "bad"}>
                {result.host}:{result.port} is {result.online ? "ONLINE" : "offline / unreachable"}
              </StatusPill>
              {result.online && result.playersOnline != null && result.playersMax != null && (
                <span className="tl-pill rounded-full border border-brand-500/25 bg-brand-500/10 px-3 py-1 text-sm font-semibold text-brand-200" data-tone="info">
                  {result.playersOnline.toLocaleString()} / {result.playersMax.toLocaleString()} players
                </span>
              )}
            </div>

            {result.online ? (
              <>
                {result.motd && (
                  <p className="mb-3 whitespace-pre-wrap break-words rounded-lg border border-white/[0.06] bg-navy-950/60 px-3 py-2 font-mono text-[13px] text-slate-300">
                    {result.motd}
                  </p>
                )}
                <KeyValue
                  rows={[
                    ["Version", result.versionName],
                    ["Protocol", result.protocol != null ? String(result.protocol) : null],
                    ["Players", result.playersOnline != null ? `${result.playersOnline} / ${result.playersMax ?? "?"}` : null],
                    ["Online now", result.sample && result.sample.length > 0 ? result.sample.join(", ") : null],
                    ["Latency", result.latencyMs != null ? `${result.latencyMs} ms` : null],
                  ]}
                />
              </>
            ) : (
              <p className="text-sm text-slate-400">
                No Minecraft server answered on that address and port. Double-check the host, the port
                (default 25565), and that the server is running and reachable from the public internet.
              </p>
            )}
          </ResultCard>
        )}
      </div>

      <div className="tl-promo rounded-xl border border-brand-500/20 bg-gradient-to-br from-brand-500/10 to-accent-blue/5 p-4">
        <p className="text-sm text-slate-300">
          Lagging or offline too often?{" "}
          <Link href="/minecraft-server-hosting" className="font-semibold text-brand-300 hover:text-brand-200">
            Nxeon Minecraft hosting
          </Link>{" "}
          runs on high-clock NVMe boxes with a dedicated IP and one-click modpacks — spun up in under a minute.
        </p>
      </div>
    </div>
  );
}

