                </span>
              )}
            </div>

            {result.online ? (
              <>
                {result.motd && (
                  <p className="mb-3 whitespace-pre-wrap break-words rounded-lg border border-white/[0.06] bg-navy-950/60 px-3 py-2 font-mono text-[13px] text-slate-300">
                    {result.motd}
                  </p>
                )}
                <KeyValue
                  rows={[
                    ["Version", result.versionName],
                    ["Protocol", result.protocol != null ? String(result.protocol) : null],
                    ["Players", result.playersOnline != null ? `${result.playersOnline} / ${result.playersMax ?? "?"}` : null],
