import { TOOLS, type Tool } from "@/lib/tools/catalog";

/**
 * Pure presentation data for the free tools on the new site (hub + the
 * tools-app template). No server-only imports, so test/nxm-tools.test.ts can
 * check it against the catalogue: every tool has an icon, a privacy line and
 * at least three valid related tools.
 */

/** One Aurora icon per tool (app/nxm/_aurora/icons.ts), so the hub reads at a
 *  glance instead of repeating the catalogue's handful of generic keys. */
export const TOOL_ICON: Record<string, string> = {
  "domain-generator": "spark",
  "whois": "search",
  "dns-lookup": "globe",
  "port-checker": "server",
  "ssl-checker": "lock",
  "http-headers": "pulse",
  "my-ip": "pin",
  "password-generator": "shield",
  "hash-generator": "check",
  "subnet-calculator": "cloud",
  "base64": "refresh",
  "json-formatter": "terminal",
  "uuid-generator": "gear",
  "minecraft-server-status": "game",
  "minecraft-skin-creator": "brush",
  "server-size-calculator": "cpu",
  "palworld-settings-generator": "paw",
  "valheim-modifiers-generator": "blade",
  "latency-test": "bolt",
};

/** The key that runs a tool, where it has one (shown in the panel footer).
 *  Tools that recompute on every change say so instead. */
