js='''/* ============ tools hub: search + category filter over the real tool catalogue ============ */
(function toolsDir() {
  const q = $('#th-q'), seg = $('.th-seg'), none = $('#th-none'), count = $('#th-count'), groups = $$('.th-grp');
  if (!q || !groups.length) return;
  const total = $$('.th-card').length;
  let cat = 'all';
  const norm = s => (s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]+/g, ' ');
  // keep ?q= and ?cat= in the address bar so a filtered view can be shared
  const sync = () => {
    try {
      const u = new URL(location.href);
      q.value.trim() ? u.searchParams.set('q', q.value.trim()) : u.searchParams.delete('q');
      cat !== 'all' ? u.searchParams.set('cat', cat) : u.searchParams.delete('cat');
      history.replaceState(history.state, '', u.pathname + u.search + u.hash);
    } catch (e) {}
  };
  const apply = () => {
    const words = norm(q.value).split(' ').filter(Boolean);
    let shown = 0;
    groups.forEach(g => {
      const inCat = cat === 'all' || g.dataset.cat === cat;
      let n = 0;
      $$('.th-card', g).forEach(c => {
        const hay = norm(c.dataset.find);
        const ok = inCat && words.every(w => hay.includes(w));
        c.hidden = !ok; if (ok) n++;
      });
      g.hidden = n === 0; shown += n;
    });
    none.hidden = shown > 0;
    if (count) {
      count.hidden = shown === 0;
      count.textContent = shown === total ? `Showing all ${total} tools.` : `Showing ${shown} of ${total} tools.`;
    }
    sync();
  };
  q.addEventListener('input', apply);
  // Enter opens the first visible match
  q.addEventListener('keydown', e => {
    if (e.key !== 'Enter') return;
    const first = $$('.th-card').find(c => !c.hidden && !c.closest('.th-grp[hidden]'));
    if (first) { e.preventDefault(); location.href = first.href; }
  });
  if (seg) seg.addEventListener('change', e => { cat = e.detail || 'all'; apply(); });
  $$('.th-sugg button').forEach(b => b.addEventListener('click', () => {
    q.value = b.dataset.q;
    const all = seg && $('button[data-v="all"]', seg);
    if (all && cat !== 'all') all.click();
    q.dispatchEvent(new Event('input')); q.focus();
  }));
  // deep links: /tools?q=dns, /tools?cat=network
  const params = new URLSearchParams(location.search);
  const pre = params.get('q'), pc = params.get('cat');
  if (pc && seg) { const b = $(`button[data-v="${CSS.escape(pc)}"]`, seg); if (b) b.click(); }
  if (pre) { q.value = pre; q.dispatchEvent(new Event('input')); }
})();
'''
