import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { TOOLS } from "../lib/tools/catalog.ts";
import { TOOL_ICON, TOOL_KBD, groupTitle, privacyLine, relatedSlugs } from "../app/nxm/_data/tools-ui.ts";
import { AU_ICONS } from "../app/nxm/_aurora/icons.ts";
import {
  dnsCount, dnsText, fmtBytes, headersText, hostPort, jsonErrorWithLocation, kvText, splitHostPort, utf8Bytes,
} from "../lib/tools/result-text.ts";

/** The free tools on the new marketing site: every catalogue tool has a
 *  route, an icon, a privacy line and related tools; the result-copy helpers
 *  produce the exact clipboard text. */

const ROOT = path.resolve(import.meta.dirname, "..");
const routes = (f: string) => JSON.parse(fs.readFileSync(path.join(ROOT, "tools/nxm/routes", f), "utf8")) as { route: string; params: { tool: string } }[];

test("every catalogue tool is routed exactly once; the skin creator keeps its own template", () => {
  const app = routes("tools-app.json"), skin = routes("tools-tool.json");
  assert.deepEqual(skin.map((r) => r.params.tool), ["minecraft-skin-creator"]);
  const all = [...app, ...skin];
  assert.equal(new Set(all.map((r) => r.params.tool)).size, all.length, "a tool is routed twice");
  assert.deepEqual(all.map((r) => r.params.tool).sort(), TOOLS.map((t) => t.slug).sort());
  for (const r of all) assert.equal(r.route, `/tools/${r.params.tool}`, "tool URLs must not change");
});

test("every tool route is a live (rewritten) route and has a generated page", () => {
  const live = new Set(JSON.parse(fs.readFileSync(path.join(ROOT, "app/nxm/_data/live-routes.json"), "utf8")) as string[]);
  for (const t of TOOLS) {
    assert.ok(live.has(`/tools/${t.slug}`), `/tools/${t.slug} missing from live-routes.json`);
    const page = fs.readFileSync(path.join(ROOT, "app/nxm/tools", t.slug, "page.tsx"), "utf8");
    const tpl = t.slug === "minecraft-skin-creator" ? "tools-tool" : "tools-app";
    assert.match(page, new RegExp(`_data/${tpl}"`), `${t.slug} should use the ${tpl} loader`);
    assert.match(page, /generateMetadata/, `${t.slug} has no metadata`);
  }
  assert.ok(live.has("/tools"));
});

test("the hub keeps its SEO registry entry", () => {
  const reg = fs.readFileSync(path.join(ROOT, "app/nxm/_seo/registry.ts"), "utf8");
  assert.match(reg, /"\/tools": \{"title": "Free Networking & Developer Tools"/);
});

test("every tool has a real Aurora icon, a privacy line and a run hint where it has one", () => {
  for (const t of TOOLS) {
    const ic = TOOL_ICON[t.slug];
    assert.ok(ic && AU_ICONS[ic], `${t.slug}: no icon`);
    assert.match(privacyLine(t), t.serverSide ? /Nxeon's servers/ : /in your browser/);
  }
  for (const slug of Object.keys(TOOL_KBD)) assert.ok(TOOLS.some((t) => t.slug === slug), `TOOL_KBD has unknown ${slug}`);
});

test("related tools: four valid, distinct, never the page itself, live picks first", () => {
  for (const t of TOOLS) {
    const r = relatedSlugs(t.slug, []);
    assert.equal(r.length, 4, t.slug);
    assert.equal(new Set(r).size, 4);
    assert.ok(!r.includes(t.slug));
    for (const s of r) assert.ok(TOOLS.some((x) => x.slug === s));
  }
  assert.deepEqual(relatedSlugs("dns-lookup", ["whois", "dns-lookup", "nope", "whois", "ssl-checker"]).slice(0, 2), ["whois", "ssl-checker"]);
  // same category tops up before the rest of the catalogue
  const net = relatedSlugs("dns-lookup", []);
  assert.ok(net.every((s) => TOOLS.find((x) => x.slug === s)!.category === "Network"));
});

test("hub headings read naturally", () => {
  assert.equal(groupTitle("Servers tools"), "Server tools");
  assert.equal(groupTitle("Network tools"), "Network tools");
});

test("result-copy helpers", () => {
  assert.equal(kvText([["IP", "1.2.3.4"], ["Reverse DNS", null], ["Latency", 12]]), "IP:      1.2.3.4\nLatency: 12");
  const recs = { A: ["1.2.3.4"], MX: ["10 mx.example.com"], TXT: [] };
  assert.equal(dnsText("example.com", recs, ["A", "AAAA", "MX", "TXT"]), "example.com\tA\t1.2.3.4\nexample.com\tMX\t10 mx.example.com");
  assert.equal(dnsCount(recs, ["A", "MX", "TXT", "NS"]), 2);
  assert.equal(headersText(301, "Moved Permanently", [["location", "https://x/"]]), "HTTP 301 Moved Permanently\nlocation: https://x/");
  assert.equal(hostPort("::1", 22), "[::1]:22");
  assert.equal(hostPort("github.com", 22), "github.com:22");
  assert.deepEqual(splitHostPort("github.com:22"), { host: "github.com", port: "22" });
  assert.deepEqual(splitHostPort("mc.hypixel.net"), { host: "mc.hypixel.net", port: "" });
  assert.equal(utf8Bytes("Grüße"), 7);
  assert.equal(fmtBytes(512), "512 B");
  assert.equal(fmtBytes(2048), "2.0 KB");
});

test("JSON errors get a line:column when the engine gives a position", () => {
  const src = '{\n  "a": 1,\n  "b": }';
  let msg = "";
  try { JSON.parse(src); } catch (e) { msg = (e as Error).message; }
  const out = jsonErrorWithLocation(src, msg);
  if (/position \d+/.test(msg) && !/line \d+ column \d+/.test(msg)) assert.match(out, /\(line 3, column 8\)$/);
  else assert.equal(out, msg);
  assert.equal(jsonErrorWithLocation("x", "Unexpected token"), "Unexpected token");
  assert.equal(jsonErrorWithLocation('{"a":}', "Unexpected token } in JSON at position 5"), "Unexpected token } in JSON at position 5 (line 1, column 6)");
});

